import json
from pathlib import Path
wanted = {'SQLITE-SEARCH-EXPOSURE-TEST', 'ITCH-SQLITE-EXACT-CANDIDATE-REVIEW', 'SQLITE-PAID-EDUCATIONAL-COMMISSION', 'NLNET-AI-POLICY-MILESTONE-FOLLOWUP', 'OPEN-SOURCE-DOCS-BOUNTY-ACCEPTANCE', 'CATALOGUE-LIVE-PILOT-INQUIRY-ACCEPTANCE', 'CATALOGUE-COMMISSION-TERMS-PROPOSAL'}
for path in sorted(Path('world/pages').glob('missions-*.json')):
    data = json.loads(path.read_text())
    rows = data if isinstance(data, list) else next((data[key] for key in ('missions', 'items', 'entries') if isinstance(data.get(key), list)), [])
    for row in rows:
        identifier = row.get('mission_id', '')
        if identifier in wanted or ('SQLITE' in identifier and ('VERDICT' in identifier or 'OUTCOME' in identifier)):
            print(json.dumps({key: row.get(key) for key in ('mission_id', 'status', 'agent_id', 'lease_expires_at', 'evidence')}))
